// ---- What's new ----
const toggle = document.getElementById('whatsnew-toggle');
const panel = document.getElementById('whatsnew');
toggle.addEventListener('click', () => {
  const open = toggle.getAttribute('aria-expanded') !== 'true';
  toggle.setAttribute('aria-expanded', open);
  panel.classList.toggle('open', open);
});

// ---- Sign-in form ----
const form = document.getElementById('signin');
const submit = document.getElementById('submit');
const formStatus = document.getElementById('form-status');
const fields = [...form.querySelectorAll('input[required]')];

function check(input) {
  const v = input.validity;
  const msg = v.valueMissing
    ? (input.type === 'email' ? 'Enter your email address.' : 'Enter your password.')
    : v.typeMismatch ? 'Enter an email address like name@yourfirm.com.' : '';
  input.setAttribute('aria-invalid', msg ? 'true' : 'false');
  document.getElementById(input.id + '-error').textContent = msg;
  return !msg;
}

fields.forEach((input) => {
  // Validate on blur only once someone has typed; re-check as they fix it.
  input.addEventListener('input', () => {
    input.dataset.dirty = '1';
    if (input.getAttribute('aria-invalid') === 'true') check(input);
  });
  input.addEventListener('blur', () => { if (input.dataset.dirty) check(input); });
});

function setBusy(busy) {
  submit.setAttribute('aria-disabled', busy);
  submit.querySelector('.label').textContent = busy ? 'Signing in' : 'Sign in';
}

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  if (submit.getAttribute('aria-disabled') === 'true') return; // double-submit guard
  const invalid = fields.filter((f) => !check(f));
  if (invalid.length) { invalid[0].focus(); return; }

  setBusy(true);
  formStatus.textContent = '';
  formStatus.classList.remove('is-error');
  try {
    const res = await fetch(form.action, { method: 'POST', body: new FormData(form), credentials: 'same-origin' });
    if (res.ok) { location.assign(res.redirected ? res.url : '/'); return; }
    fail(res.status === 401 || res.status === 403
      ? "That email and password don't match. Try again or reset your password."
      : "Tallyhouse couldn't sign you in right now. Try again in a moment.");
  } catch {
    fail("Couldn't reach Tallyhouse. Check your connection and try again.");
  }
});

function fail(msg) {
  setBusy(false);
  formStatus.classList.add('is-error');
  formStatus.textContent = msg;
}

// ---- Invoice preview (sample data) ----
const CLIENTS = [
  'Harbor & Pine Dental', 'Okafor Joinery', 'Brightwater Veterinary', 'Lindqvist Architects',
  'Mesa Verde Taqueria', 'Northfield Cycle Co.', 'Patel Family Pharmacy', 'Quill & Ledger Books',
  'Rosales Landscaping', 'Saltmarsh Oyster Bar', 'Tanaka Physiotherapy', 'Upland Roofing Ltd',
  'Vasquez & Moore Legal', 'Westgate Print Shop', 'Yellowfin Charters', 'Abernathy Plumbing',
];
const STAGES = { draft: 1, sent: 2, viewed: 3, overdue: 3, paid: 5 };
const LABELS = { draft: 'Draft', sent: 'Sent', viewed: 'Viewed', overdue: 'Overdue', paid: 'Paid' };
const RANK = { overdue: 0, draft: 1, sent: 2, viewed: 3, paid: 4 };
const DAY = 864e5;

// ponytail: seeded LCG so the sample reads the same on every load
let seed = 7;
const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);

const today = new Date(); today.setHours(0, 0, 0, 0);
const invoices = Array.from({ length: 40 }, (_, i) => {
  const age = Math.floor(i * 1.6 + rand() * 2);
  const issued = new Date(today - age * DAY);
  const due = new Date(+issued + (rand() < 0.6 ? 30 : 14) * DAY);
  let status = rand() < Math.min(0.85, age / 40) ? 'paid'
    : age <= 1 && rand() < 0.6 ? 'draft'
    : due < today ? 'overdue'
    : rand() < 0.5 ? 'viewed' : 'sent';
  return {
    client: CLIENTS[Math.floor(rand() * CLIENTS.length)],
    number: 'TH-' + (2140 - i),
    issued, due, status,
    amount: Math.round((180 + rand() * rand() * 9000) * 100) / 100,
  };
});

const dateFmt = new Intl.DateTimeFormat(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
const money = new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' });
const tbody = document.getElementById('rows');
const sortStatus = document.getElementById('sort-status');
const headers = [...document.querySelectorAll('thead th')];

function statusCell(s) {
  return `<span class="status ${s}"><svg class="tally" data-stage="${STAGES[s]}" aria-hidden="true"><use href="#gate"/></svg>${LABELS[s]}</span>`;
}

function render(key, dir) {
  const sign = dir === 'ascending' ? 1 : -1;
  const val = (r) => (key === 'status' ? RANK[r.status] : r[key]);
  const rows = [...invoices].sort((a, b) => {
    const x = val(a), y = val(b);
    return sign * (typeof x === 'string' ? x.localeCompare(y) : x - y);
  });
  tbody.innerHTML = rows.map((r) => `<tr>
    <td title="${r.client}">${r.client}</td>
    <td class="mono">${r.number}</td>
    <td>${dateFmt.format(r.issued)}</td>
    <td>${dateFmt.format(r.due)}</td>
    <td class="num">${money.format(r.amount)}</td>
    <td>${statusCell(r.status)}</td></tr>`).join('');
  headers.forEach((th) => {
    if (th.dataset.key === key) th.setAttribute('aria-sort', dir);
    else th.removeAttribute('aria-sort');
  });
}

function sortBy(key, dir, announce) {
  render(key, dir);
  const url = new URL(location);
  url.searchParams.set('sort', key);
  url.searchParams.set('dir', dir === 'ascending' ? 'asc' : 'desc');
  history.replaceState(null, '', url);
  if (announce) {
    const name = headers.find((th) => th.dataset.key === key).textContent;
    sortStatus.textContent = `Sorted by ${name}, ${dir}`;
  }
}

headers.forEach((th) => th.querySelector('button').addEventListener('click', () => {
  const same = th.getAttribute('aria-sort');
  const dir = same ? (same === 'ascending' ? 'descending' : 'ascending')
    : th.dataset.key === 'client' || th.dataset.key === 'status' ? 'ascending' : 'descending';
  sortBy(th.dataset.key, dir, true);
}));

document.getElementById('preview-count').textContent = `${invoices.length} invoices · sample data`;
const params = new URLSearchParams(location.search);
const initialKey = headers.some((th) => th.dataset.key === params.get('sort')) ? params.get('sort') : 'issued';
render(initialKey, params.get('dir') === 'asc' ? 'ascending' : 'descending');

