const form = document.getElementById('signin');
const submit = document.getElementById('submit');
const formStatus = document.getElementById('form-status');
const fields = [...form.querySelectorAll('input[required]')];

function check(input) {
  const v = input.validity;
  const msg = v.valueMissing
    ? (input.type === 'email' ? 'Enter your email address.' : 'Enter your password.')
    : v.typeMismatch ? 'Enter an email address like name@yourfirm.com.' : '';
  input.setAttribute('aria-invalid', msg ? 'true' : 'false');
  document.getElementById(input.id + '-error').textContent = msg;
  return !msg;
}

fields.forEach((input) => {
  // Validate on blur only once someone has typed; re-check as they fix it.
  input.addEventListener('input', () => {
    input.dataset.dirty = '1';
    if (input.getAttribute('aria-invalid') === 'true') check(input);
  });
  input.addEventListener('blur', () => { if (input.dataset.dirty) check(input); });
});

function setBusy(busy) {
  submit.setAttribute('aria-disabled', busy);
  submit.querySelector('.label').textContent = busy ? 'Signing in' : 'Sign in';
}

