:root {
  --bg: oklch(0.985 0.004 160);
  --surface: oklch(1 0 0);
  --ink: oklch(0.22 0.012 160);
  --muted: oklch(0.46 0.012 160);
  --line: oklch(0.9 0.008 160);      /* decorative separators only */
  --field: oklch(0.58 0.01 160);     /* control edges, >=3:1 on surface */
  --accent: oklch(0.45 0.11 160);
  --accent-hover: oklch(0.38 0.1 160);
  --danger: oklch(0.5 0.17 27);
  --ease: cubic-bezier(0.25, 1, 0.5, 1); /* ease-out quart */
  --row: 28px;
  --tap: 24px;
  color-scheme: light;
}
@media (pointer: coarse) {
  :root { --row: 44px; --tap: 44px; }
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 1rem/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}
h1, h2 { text-wrap: balance; margin: 0; }
a { color: var(--accent); }
a:hover { color: var(--accent-hover); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.muted { color: var(--muted); margin: 0; }
.visually-hidden {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap;
}

/* Tally gate: faint strokes for stages not reached, solid for reached, gate closes at 5 */
.tally { width: 20px; height: 14px; flex: none; }
.tally path { fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; opacity: 0.22; }
.tally .s5 { opacity: 0; }
[data-stage="1"] .s1,
[data-stage="2"] :is(.s1, .s2),
[data-stage="3"] :is(.s1, .s2, .s3),
[data-stage="5"] path { opacity: 1; }

/* Top bar + What's new */
.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding: 0.75rem clamp(1rem, 4vw, 2.5rem);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}
.brand {
  display: inline-flex; align-items: center; gap: 0.5rem;
  color: var(--ink); font-weight: 650; text-decoration: none;
}
.brand .tally { color: var(--accent); width: 24px; height: 17px; }
.btn-quiet {
  font: inherit; font-size: 0.875rem; color: var(--ink);
  background: none; border: 1px solid var(--field); border-radius: 6px;
  min-height: max(var(--tap), 32px); padding: 0 0.75rem; cursor: pointer;
}
.btn-quiet:hover { background: var(--bg); }
.btn-quiet[aria-expanded="true"] { background: var(--ink); color: var(--surface); border-color: var(--ink); }

.whatsnew {
  display: grid; grid-template-rows: 0fr; visibility: hidden;
  background: var(--surface); border-bottom: 1px solid transparent;
  transition: grid-template-rows 220ms var(--ease), visibility 0s linear 220ms, border-color 0s linear 220ms;
}
.whatsnew.open {
  grid-template-rows: 1fr; visibility: visible; border-color: var(--line);
  transition: grid-template-rows 220ms var(--ease);
}
.whatsnew-inner { overflow: hidden; min-height: 0; }
.whatsnew ul {
  margin: 0; padding: 1rem clamp(1rem, 4vw, 2.5rem) 1.25rem 2.75rem;
  max-width: 75ch; display: grid; gap: 0.5rem; font-size: 0.875rem;
}

/* Hero + form */
main { padding: 0 clamp(1rem, 4vw, 2.5rem) 3rem; max-width: 1280px; margin: 0 auto; }
.intro {
  display: grid; gap: 2rem; align-items: center;
  padding: clamp(2rem, 6vw, 4.5rem) 0 2.5rem;
}
@media (min-width: 900px) {
  .intro { grid-template-columns: 1fr minmax(320px, 380px); gap: 4rem; }
}
h1 { font-size: 2rem; line-height: 1.2; font-weight: 700; letter-spacing: -0.02em; max-width: 20ch; }
.lede { font-size: 20px; line-height: 1.5; color: var(--muted); margin: 0.75rem 0 0; max-width: 42ch; }

.signin {
  background: var(--surface); border: 1px solid var(--line); border-radius: 10px;
  padding: 1.5rem; display: grid; gap: 1rem;
  box-shadow: 0 1px 2px oklch(0.22 0.012 160 / 0.06), 0 8px 24px oklch(0.22 0.012 160 / 0.06);
}
.signin h2 { font-size: 1.2rem; }
.field { display: grid; gap: 0.25rem; }
.label-row { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
.label-row a { font-size: 0.875rem; }
label { font-size: 0.875rem; font-weight: 550; }
input[type="email"], input[type="password"] {
  font: inherit; color: var(--ink); background: var(--surface);
  border: 1px solid var(--field); border-radius: 6px;
  min-height: 44px; padding: 0 0.75rem; width: 100%;
}
input:hover { border-color: var(--ink); }
input[aria-invalid="true"] { border-color: var(--danger); border-width: 2px; padding-inline: calc(0.75rem - 1px); }
.error { margin: 0; font-size: 0.875rem; color: var(--danger); min-height: 0; }
.error:empty { display: none; }
.check { display: flex; align-items: center; gap: 0.5rem; font-weight: 400; min-height: 44px; cursor: pointer; }
.check input { width: 18px; height: 18px; margin: 0; accent-color: var(--accent); }

.btn-primary {
  font: inherit; font-weight: 600; color: var(--surface);
  background: var(--accent); border: 0; border-radius: 6px;
  min-height: 44px; width: 100%; cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem;
}
.btn-primary:hover { background: var(--accent-hover); }
.btn-primary:active { transform: translateY(1px); }
.btn-primary .tally { display: none; }
.btn-primary[aria-disabled="true"] { cursor: progress; background: var(--accent-hover); }
.btn-primary[aria-disabled="true"] .tally { display: block; }
/* In flight: strokes tally up one by one, then the gate closes */
.btn-primary[aria-disabled="true"] .tally path { animation: tally 1.2s steps(1) infinite; }
.btn-primary[aria-disabled="true"] .tally .s2 { animation-delay: 0.2s; }
.btn-primary[aria-disabled="true"] .tally .s3 { animation-delay: 0.4s; }
.btn-primary[aria-disabled="true"] .tally .s4 { animation-delay: 0.6s; }
.btn-primary[aria-disabled="true"] .tally .s5 { animation-delay: 0.8s; }
@keyframes tally { 0% { opacity: 0.22; } 20%, 100% { opacity: 1; } }
.form-status { margin: 0; font-size: 0.875rem; }
.form-status:empty { display: none; }
.form-status.is-error { color: var(--danger); }

/* Invoice preview */
.preview-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 0.75rem; }
.preview-head h2 { font-size: 1.2rem; }
.preview-head .muted { font-size: 0.875rem; }
.table-scroll {
  max-height: min(70vh, 560px); overflow: auto;
  background: var(--surface); border: 1px solid var(--line); border-radius: 10px;
}
@media (max-height: 500px) { .table-scroll { max-height: none; } }
table {
  width: 100%; min-width: 640px; table-layout: fixed;
  border-collapse: separate; border-spacing: 0;
  font-size: 0.8125rem; font-variant-numeric: tabular-nums;
}
th:nth-child(1) { width: 30%; }
th:nth-child(2) { width: 14%; }
th:nth-child(3), th:nth-child(4) { width: 14%; }
th:nth-child(5) { width: 13%; }
th:nth-child(6) { width: 15%; }
th, td { text-align: start; padding: 0 0.625rem; height: var(--row); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
td { border-bottom: 1px solid var(--line); }
tbody tr:last-child td { border-bottom: 0; }
tbody tr:hover td { background: oklch(0.97 0.008 160); }
.num { text-align: end; }
td.mono { font-family: ui-monospace, "Cascadia Mono", Consolas, monospace; font-size: 0.75rem; }

thead th {
  position: sticky; top: 0; z-index: 2;
  background: var(--surface); padding: 0 0.25rem;
  box-shadow: inset 0 -1px 0 var(--field);
}
th button {
  font: inherit; font-weight: 600; color: var(--ink);
  background: none; border: 0; border-radius: 4px; cursor: pointer;
  min-height: var(--tap); padding: 0 0.375rem; width: 100%;
  display: inline-flex; align-items: center; gap: 0.25rem; text-align: inherit;
}
th.num button { justify-content: flex-end; }
th button:hover { background: var(--bg); }
th button::after { content: "↕"; color: var(--muted); font-size: 0.75em; }
th[aria-sort="ascending"] button::after { content: "↑"; color: var(--ink); }
th[aria-sort="descending"] button::after { content: "↓"; color: var(--ink); }
th button:focus-visible { outline-offset: -2px; }

/* Client column stays put when the table scrolls sideways */
th:first-child, td:first-child { position: sticky; left: 0; z-index: 1; background: var(--surface); }
thead th:first-child { z-index: 3; }
tbody tr:hover td:first-child { background: oklch(0.97 0.008 160); }

.status { display: inline-flex; align-items: center; gap: 0.375rem; }
.status .tally { color: var(--accent); }
.status.overdue { color: var(--danger); font-weight: 600; }
.status.overdue .tally { color: var(--danger); }
.pad { padding: 1rem; }

@media (prefers-reduced-motion: reduce) {
  .whatsnew, .whatsnew.open { transition: none; }
  .btn-primary[aria-disabled="true"] .tally path { animation: none; opacity: 1; }
  .btn-primary[aria-disabled="true"] .tally .s5 { opacity: 0; }
}
